<script setup>
import{onMounted,reactive,ref}from'vue';import{selfEvaluationApi as api}from'../../selfEvaluationApi'
const tasks=ref([]),versions=ref([]),orgs=ref([]),selected=ref(null),formData=ref(null),message=ref(''),messageType=ref('success'),showCreate=ref(false)
const form=reactive({taskCode:'',taskName:'',evaluationYear:new Date().getFullYear(),taskType:'ANNUAL',startDate:'',endDate:'',description:'',indicatorVersionId:'',orgUnitIds:[]})
function notice(text,type='success'){message.value=text;messageType.value=type}
async function load(){try{[tasks.value,versions.value,orgs.value]=await Promise.all([api.tasks(),api.versions(),api.orgs()])}catch(e){notice(e.message,'error')}}
async function create(){if(!form.taskCode.trim()||!form.taskName.trim()||!form.indicatorVersionId||!form.orgUnitIds.length||!form.startDate||!form.endDate){notice('请完整填写任务编码、名称、日期、指标版本和参评机构','error');return}if(form.startDate>form.endDate){notice('结束日期不能早于开始日期','error');return}try{await api.createTask({...form});showCreate.value=false;notice('自评任务草稿已创建');await load()}catch(e){notice(e.message,'error')}}
async function open(x){try{selected.value=await api.task(x.id);formData.value=null}catch(e){notice(e.message,'error')}}
async function publish(x){try{await api.publish(x.id);notice('任务已发布并冻结三级指标快照');await load();await open(x)}catch(e){notice(e.message,'error')}}
async function cancelTask(x){const opinion=prompt('请输入取消原因');if(!opinion)return;try{await api.cancel(x.id,{action:'CANCEL',opinion});notice('任务已取消');selected.value=null;formData.value=null;await load()}catch(e){notice(e.message,'error')}}
async function openForm(x){try{formData.value=await api.form(x.id)}catch(e){notice(e.message,'error')}}
async function saveEntry(x){try{await api.saveEntry(x.id,{selfScore:x.self_score,performanceDescription:x.performance_description,completionStatus:x.completion_status,rowVersion:x.row_version});formData.value=await api.form(formData.value.id);notice('自评指标已暂存')}catch(e){notice(e.message,'error')}}
async function submit(){try{formData.value=await api.submit(formData.value.id,{opinion:'提交部门自评'});notice('自评已提交');selected.value=await api.task(selected.value.id)}catch(e){notice(e.message,'error')}}
async function review(action){const opinion=prompt(action==='CONFIRM'?'确认意见':'退回意见');if(!opinion)return;try{formData.value=await api.review(formData.value.id,{action,opinion});notice(action==='CONFIRM'?'自评已完成':'自评已退回');selected.value=await api.task(selected.value.id);await load()}catch(e){notice(e.message,'error')}}
onMounted(load)
</script>
<template><section class="page active"><div class="alert alert-info">部门自评使用已发布三级指标快照；规则检查代替AI初审，提交后只读，退回后可修改重提。</div><div v-if="message" class="alert" :class="messageType==='error'?'alert-danger':'alert-success'">{{message}}</div>
<div class="card"><div class="card-header"><h3>📋 自评任务看板</h3><button class="btn btn-primary" @click="showCreate=true">创建任务</button></div><table><thead><tr><th>任务</th><th>年度</th><th>类型</th><th>指标版本</th><th>机构</th><th>进度</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-if="!tasks.length"><td colspan="8">暂无任务；请先发布指标版本</td></tr><tr v-for="x in tasks" :key="x.id"><td>{{x.task_name}}</td><td>{{x.evaluation_year}}</td><td>{{x.task_type}}</td><td>{{x.version_name}}</td><td>{{x.org_count}}</td><td>{{x.progress}}%</td><td>{{x.status}}</td><td><button class="btn btn-sm btn-outline" @click="open(x)">详情</button> <button v-if="x.status==='DRAFT'" class="btn btn-sm btn-primary" @click="publish(x)">发布</button> <button v-if="!['COMPLETED','CANCELLED'].includes(x.status)" class="btn btn-sm btn-outline" @click="cancelTask(x)">取消</button></td></tr></tbody></table></div>
<div v-if="selected" class="card"><div class="card-header"><h3>{{selected.task_name}} · 机构进度</h3></div><table><thead><tr><th>机构</th><th>完成指标</th><th>总分</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="x in selected.organizations" :key="x.id"><td>{{x.unit_name}}</td><td>{{x.completed_items}}/{{x.total_items}}</td><td>{{x.total_score}}</td><td>{{x.status}}</td><td><button class="btn btn-sm btn-primary" :disabled="selected.status==='DRAFT'" @click="openForm(x)">填报/复核</button></td></tr></tbody></table></div>
<div v-if="formData" class="card"><div class="card-header"><h3>{{formData.unit_name}} · 自评填报</h3><span class="tag tag-info">{{formData.status}}</span></div><table><thead><tr><th>指标</th><th>标准分</th><th>自评分</th><th>完成情况</th><th>履职说明</th><th>操作</th></tr></thead><tbody><tr v-for="x in formData.entries" :key="x.id"><td>{{x.indicator_code}} {{x.indicator_name}}</td><td>{{x.standard_score}}</td><td><input v-model.number="x.self_score" type="number" min="0" :max="x.standard_score" :disabled="!['NOT_STARTED','DRAFT','RETURNED'].includes(formData.status)"></td><td><input v-model="x.completion_status" :disabled="!['NOT_STARTED','DRAFT','RETURNED'].includes(formData.status)"></td><td><textarea v-model="x.performance_description" :disabled="!['NOT_STARTED','DRAFT','RETURNED'].includes(formData.status)"></textarea></td><td><button v-if="['NOT_STARTED','DRAFT','RETURNED'].includes(formData.status)" class="btn btn-sm btn-outline" @click="saveEntry(x)">暂存</button></td></tr></tbody></table><div class="btn-group"><button v-if="['DRAFT','RETURNED'].includes(formData.status)" class="btn btn-primary" @click="submit">提交复核</button><template v-if="formData.status==='SUBMITTED'"><button class="btn btn-primary" @click="review('CONFIRM')">确认完成</button><button class="btn btn-outline" @click="review('RETURN')">退回修改</button></template></div></div>
<div v-if="showCreate" class="modal-overlay" @click.self="showCreate=false"><div class="modal"><h3>创建自评任务</h3><div class="form-grid"><div class="form-item"><label>编码</label><input v-model="form.taskCode"></div><div class="form-item"><label>名称</label><input v-model="form.taskName"></div><div class="form-item"><label>年度</label><input v-model.number="form.evaluationYear" type="number"></div><div class="form-item"><label>类型</label><select v-model="form.taskType"><option value="ANNUAL">年度</option><option value="SPECIAL">专项</option></select></div><div class="form-item"><label>开始日期</label><input v-model="form.startDate" type="date"></div><div class="form-item"><label>结束日期</label><input v-model="form.endDate" type="date"></div><div class="form-item full"><label>已发布指标版本</label><select v-model="form.indicatorVersionId"><option value="">请选择</option><option v-for="x in versions" :key="x.id" :value="x.id">{{x.system_name}} / {{x.version_name}}（{{x.item_count}}项）</option></select></div><div class="form-item full"><label>参评机构</label><div class="choice-list"><label v-for="x in orgs" :key="x.id"><input v-model="form.orgUnitIds" type="checkbox" :value="x.id"> {{x.unit_name}}</label></div></div><div class="form-item full"><label>说明</label><textarea v-model="form.description"></textarea></div></div><button class="btn btn-primary" @click="create">保存草稿</button> <button class="btn btn-outline" @click="showCreate=false">取消</button></div></div>
</section></template>
<style scoped>.modal-overlay{position:fixed;inset:0;background:#0006;z-index:1000;display:flex;align-items:center;justify-content:center}.modal{background:#fff;padding:22px;border-radius:12px;width:min(800px,94vw);max-height:88vh;overflow:auto}.form-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.full{grid-column:1/-1}.choice-list{display:grid;grid-template-columns:repeat(2,1fr);max-height:180px;overflow:auto}@media(max-width:700px){.form-grid{grid-template-columns:1fr}.full{grid-column:auto}}</style>
